fn is_nested(s: Vec<i8>) -> bool {
    // We want to find a subsequence matching [0, 0, 1, 1].
    // We use a small DP array where dp[k] means "we have matched
    // the first k elements of the pattern so far".
    let pattern = [0i8, 0, 1, 1];
    // dp[0] = true: we've trivially matched zero elements of the pattern.
    // dp[1] through dp[4] = false initially.
    let mut dp = [false; 5];
    dp[0] = true;

    for x in s {
        // Update dp in reverse so we don't reuse an updated state in the same iteration.
        for k in (0..4).rev() {
            if dp[k] && x == pattern[k] {
                dp[k + 1] = true;
            }
        }
        // If we've matched all 4 elements, we can return early.
        if dp[4] {
            return true;
        }
    }

    dp[4]
}

